3	namespace chatai.Core.Helper
4	{
5	    /// <summary>
6	    /// exploration.history_json 欄位的序列化格式：[{"role":"user"|"model","text":"..."}]，
7	    /// 跟前端 ConversationTurn 型別、IAdvisingChatService.QueryStreamAsync 的 history 參數
8	    /// 共用同一組 (Role, Text) 資料形狀。RunController 與 ExplorationController 都要用到，
9	    /// 集中在這裡轉換，避免兩邊各寫一份。
10	    /// </summary>
11	    public static class ExplorationHistoryJson
12	    {
13	        private record Turn(string role, string text);
14	
15	        public static List<(string Role, string Text)> Parse(string? json)
16	        {
17	            if (string.IsNullOrWhiteSpace(json))
18	                return new List<(string Role, string Text)>();
19	
20	            var turns = JsonSerializer.Deserialize<List<Turn>>(json) ?? new List<Turn>();
21	            // Claude/Gemini 的多輪對話 API 都不接受空白內容的訊息；history 裡只要混進一筆空白
22	            // 訊息（例如曾經允許送出空白答案，見 RunController.cs 的 input_value 驗證），這筆
23	            // 探索之後每輪都要重送整段 history，會永久卡在同一個 400 錯誤。讀取時直接濾掉這種
24	            // 壞資料，讓已經中招的舊紀錄也能自動復原，不用另外寫一次性的資料修復腳本。
25	            return turns
26	                .Where(t => !string.IsNullOrWhiteSpace(t.role) && !string.IsNullOrWhiteSpace(t.text))
27	                .Select(t => (t.role, t.text))
28	                .ToList();
29	        }
30	
31	        public static string Serialize(IReadOnlyList<(string Role, string Text)> history)
32	        {
33	            var turns = history.Select(h => new Turn(h.Role, h.Text));
34	            return JsonSerializer.Serialize(turns);
35	        }
36	    }
37	}
