627	        /// <summary>
628	        /// OpenAI Chat Completions streaming（model=openai）。history 的 "model" 角色轉成 OpenAI 的 "assistant"。
629	        /// </summary>
630	        private async IAsyncEnumerable<GeminiStreamChunk> QueryOpenAiStreamAsync(
631	            string question,
632	            IReadOnlyList<(string Role, string Text)> history)
633	        {
634	            var client = CreateOpenAiClient();
635	
636	            var messages = new List<object> { new { role = "system", content = BuildSystemInstruction(ShouldIncludeResourceList(history)) } };
637	            messages.AddRange(history.Select(h => (object)new { role = h.Role == "model" ? "assistant" : "user", content = h.Text }));
638	            messages.Add(new { role = "user", content = question });
639	
640	            var requestBody = new
641	            {
642	                model = _appSetting.OpenAiModel,
643	                messages,
644	                temperature = 0.7,
645	                stream = true,
646	            };
647	
648	            using var content = new StringContent(JsonSerializer.Serialize(requestBody), Encoding.UTF8, "application/json");
649	            using var request = new HttpRequestMessage(HttpMethod.Post, "/v1/chat/completions") { Content = content };
650	
651	            using var resp = await client.SendAsync(request, HttpCompletionOption.ResponseHeadersRead);
652	
653	            if (!resp.IsSuccessStatusCode)
654	            {
655	                var errorBody = await resp.Content.ReadAsStringAsync();
656	                _logger.LogError("OpenAI chat/completions (flow 7) failed: {Status} {Body}", resp.StatusCode, errorBody);
657	                yield return new GeminiStreamChunk { Error = $"OpenAI API 呼叫失敗 ({(int)resp.StatusCode}): {errorBody}" };
658	                yield break;
659	            }
660	
661	            await using var stream = await resp.Content.ReadAsStreamAsync();
662	            using var reader = new StreamReader(stream, Encoding.UTF8);
663	
664	            string? line;
665	            while ((line = await reader.ReadLineAsync()) != null)
666	            {
667	                if (!line.StartsWith("data: "))
668	                    continue;
669	
670	                var data = line["data: ".Length..];
671	                if (data == "[DONE]")
672	                    break;
673	
674	                using var doc = JsonDocument.Parse(data);
675	
676	                if (!doc.RootElement.TryGetProperty("choices", out var choices) || choices.GetArrayLength() == 0)
677	                    continue;
678	
679	                if (choices[0].TryGetProperty("delta", out var delta) &&
680	                    delta.TryGetProperty("content", out var contentEl))
681	                {
682	                    var text = contentEl.GetString();
683	                    if (!string.IsNullOrEmpty(text))
684	                        yield return new GeminiStreamChunk { Delta = text };
685	                }
686	            }
687	
688	            yield return new GeminiStreamChunk { Done = true, Source = "" };
689	        }
