691	        /// <summary>
692	        /// Claude Messages API streaming（model=claude）。history 的角色（user/model）跟 Claude 的
693	        /// （user/assistant）用同樣的方式轉換。
694	        /// </summary>
695	        private async IAsyncEnumerable<GeminiStreamChunk> QueryClaudeStreamAsync(
696	            string question,
697	            IReadOnlyList<(string Role, string Text)> history)
698	        {
699	            var client = CreateClaudeClient();
700	
701	            var messages = history
702	                .Select(h => new { role = h.Role == "model" ? "assistant" : "user", content = h.Text })
703	                .Append(new { role = "user", content = question })
704	                .ToArray();
705	
706	            var requestBody = new
707	            {
708	                model = _appSetting.ClaudeModel,
709	                system = BuildSystemInstruction(ShouldIncludeResourceList(history)),
710	                messages,
711	                max_tokens = 2048,
712	                temperature = 0.7,
713	                stream = true,
714	            };
715	
716	            using var content = new StringContent(JsonSerializer.Serialize(requestBody), Encoding.UTF8, "application/json");
717	            using var request = new HttpRequestMessage(HttpMethod.Post, "/v1/messages") { Content = content };
718	
719	            using var resp = await client.SendAsync(request, HttpCompletionOption.ResponseHeadersRead);
720	
721	            if (!resp.IsSuccessStatusCode)
722	            {
723	                var errorBody = await resp.Content.ReadAsStringAsync();
724	                _logger.LogError("Claude messages (flow 7) failed: {Status} {Body}", resp.StatusCode, errorBody);
725	                yield return new GeminiStreamChunk { Error = $"Claude API 呼叫失敗 ({(int)resp.StatusCode}): {errorBody}" };
726	                yield break;
727	            }
728	
729	            await using var stream = await resp.Content.ReadAsStreamAsync();
730	            using var reader = new StreamReader(stream, Encoding.UTF8);
731	
732	            string? line;
733	            while ((line = await reader.ReadLineAsync()) != null)
734	            {
735	                if (!line.StartsWith("data: "))
736	                    continue;
737	
738	                using var doc = JsonDocument.Parse(line["data: ".Length..]);
739	
740	                if (!doc.RootElement.TryGetProperty("type", out var typeEl) ||
741	                    typeEl.GetString() != "content_block_delta")
742	                    continue;
743	
744	                if (doc.RootElement.TryGetProperty("delta", out var delta) &&
745	                    delta.TryGetProperty("text", out var textEl))
746	                {
747	                    var text = textEl.GetString();
748	                    if (!string.IsNullOrEmpty(text))
749	                        yield return new GeminiStreamChunk { Delta = text };
750	                }
751	            }
752	
753	            yield return new GeminiStreamChunk { Done = true, Source = "" };
754	        }
755	    }
